<?php
declare(strict_types=1);
namespace QualitySystem\Services;
use PDO;use RuntimeException;use QualitySystem\Domain\ProgramSpecification\ProgramSpecification;use QualitySystem\Domain\ProgramSpecification\ProgramSpecificationValidator;use QualitySystem\Repositories\ProgramSpecificationRepository;use QualitySystem\Security\AuditLogger;use QualitySystem\Security\PermissionMatrix;
final class ProgramSpecificationService
{
    public function __construct(private readonly PDO $pdo,private readonly ProgramSpecificationRepository $repository){}
    public function save(array $input,string $role,int $userId,?int $id=null):int{$action=$id===null?'create':'update';if(!PermissionMatrix::allows($role,'programs',$action))throw new RuntimeException('Forbidden',403);$errors=ProgramSpecificationValidator::validate($input);if($errors)throw new ProgramSpecificationValidationException($errors);if($id!==null&&!$this->repository->findScoped($id,$role,$userId))throw new RuntimeException('Program specification not found.',404);$fields=[];foreach(ProgramSpecificationRepository::EDITABLE as $field){$value=trim((string)($input[$field]??''));$fields[$field]=$value===''?null:$value;}$fields['study_plan_id']=$fields['study_plan_id']!==null?(int)$fields['study_plan_id']:null;$fields['total_credit_hours']=$fields['total_credit_hours']!==null?(int)$fields['total_credit_hours']:null;$fields['approval_status']=$fields['approval_status']??'Draft';$fields['status']=$fields['approval_status'];$this->pdo->beginTransaction();try{$saved=$this->repository->save(new ProgramSpecification($id,$fields));if($id===null){$grant=$this->pdo->prepare('INSERT IGNORE INTO user_program_access(user_id,program_specification_id) VALUES(:user,:program)');$grant->execute([':user'=>$userId,':program'=>$saved]);}AuditLogger::record($this->pdo,'program_specification_'.$action,'allowed','Program Specifications',[],'program_specification',$saved);$this->pdo->commit();return$saved;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
    public function delete(int $id,string $role,int $userId):void{if(!PermissionMatrix::allows($role,'programs','delete'))throw new RuntimeException('Forbidden',403);if(!$this->repository->findScoped($id,$role,$userId))throw new RuntimeException('Program specification not found.',404);$linked=$this->repository->linkedCounts($id);if($linked)throw new RuntimeException('Archive this specification instead; linked records prevent deletion.',409);$this->pdo->beginTransaction();try{$this->repository->delete($id);AuditLogger::record($this->pdo,'program_specification_delete','allowed','Program Specifications',[],'program_specification',$id);$this->pdo->commit();}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
}
final class ProgramSpecificationValidationException extends RuntimeException{public function __construct(public readonly array $errors){parent::__construct('Validation failed.',422);}}
